INSERT INTO tahun_anggaran (tahun,is_locked) VALUES (YEAR(CURDATE()),0) ON DUPLICATE KEY UPDATE tahun=VALUES(tahun);
INSERT INTO jenis_biaya (kode,nama,satuan) VALUES ('TRANSPORT','Transportasi','orang'),('UANG_HARIAN','Uang Harian','orang/hari'),('PENGINAPAN','Penginapan','malam'),('TIKET','Tiket Perjalanan','tiket'),('SEWA_KENDARAAN','Sewa Kendaraan','hari'),('KONSUMSI','Konsumsi','orang'),('ATK','Alat Tulis Kantor','paket'),('DOKUMENTASI','Dokumentasi','kegiatan') ON DUPLICATE KEY UPDATE nama=VALUES(nama);
INSERT INTO sumber_dana (kode,nama) VALUES ('APBD','APBD Sekretariat DPRD'),('DAU','Dana Alokasi Umum'),('DAK','Dana Alokasi Khusus'),('BOK','Bantuan Operasional Kegiatan'),('HIBAH','Dana Hibah'),('LAINNYA','Sumber Dana Lainnya') ON DUPLICATE KEY UPDATE nama=VALUES(nama);
INSERT INTO penerima (nama,tipe,jabatan,periode_mulai,periode_akhir) VALUES ('Ketua DPRD','DPRD','Ketua',2024,2029),('Wakil Ketua I','DPRD','Wakil Ketua',2024,2029),('Wakil Ketua II','DPRD','Wakil Ketua',2024,2029),('Anggota DPRD 1','DPRD','Anggota',2024,2029),('Anggota DPRD 2','DPRD','Anggota',2024,2029),('Anggota DPRD 3','DPRD','Anggota',2024,2029),('Anggota DPRD 4','DPRD','Anggota',2024,2029),('Anggota DPRD 5','DPRD','Anggota',2024,2029),('Anggota DPRD 6','DPRD','Anggota',2024,2029),('Anggota DPRD 7','DPRD','Anggota',2024,2029),('Pendamping 1','PENDAMPING','Jabatan Khusus',NULL,NULL),('Pendamping 2','PENDAMPING','Jabatan Khusus',NULL,NULL),('Pendamping 3','PENDAMPING','Jabatan Khusus',NULL,NULL),('Pendamping 4','PENDAMPING','Jabatan Khusus',NULL,NULL),('Pendamping 5','PENDAMPING','Jabatan Khusus',NULL,NULL);
INSERT INTO anggaran (tahun_anggaran_id,penerima_id,pagu) SELECT t.id,p.id,100000000 FROM tahun_anggaran t JOIN penerima p ON t.tahun=YEAR(CURDATE()) ON DUPLICATE KEY UPDATE pagu=VALUES(pagu);
INSERT INTO users (username,password,nama,role_id,is_active,wajib_ganti_password) SELECT 'admin','$2y$10$nZPUGsK/.d9Z1bafYrSlFOgeMlEGx9Yvk/bMD0YT7.3QAw/g96KYK','Administrator',r.id,1,1 FROM roles r WHERE r.kode='ADMIN' ON DUPLICATE KEY UPDATE nama=VALUES(nama),role_id=VALUES(role_id),is_active=1,wajib_ganti_password=1;
INSERT INTO users (username,password,nama,role_id,is_active,wajib_ganti_password) SELECT x.username,'$2y$10$nZPUGsK/.d9Z1bafYrSlFOgeMlEGx9Yvk/bMD0YT7.3QAw/g96KYK',x.nama,r.id,1,1 FROM (SELECT 'superadmin' username,'Super Admin' nama,'SUPERADMIN' role_code UNION ALL SELECT 'pptk','PPTK','PPTK' UNION ALL SELECT 'operator','Operator','OPERATOR' UNION ALL SELECT 'pimpinan','Pimpinan','PIMPINAN') x JOIN roles r ON r.kode=x.role_code ON DUPLICATE KEY UPDATE nama=VALUES(nama),role_id=VALUES(role_id),is_active=1,wajib_ganti_password=1;
INSERT INTO users (username,password,nama,role_id,penerima_id,is_active,wajib_ganti_password) SELECT CONCAT('pendamping',p.id),'$2y$10$nZPUGsK/.d9Z1bafYrSlFOgeMlEGx9Yvk/bMD0YT7.3QAw/g96KYK',p.nama,r.id,p.id,1,1 FROM penerima p JOIN roles r ON r.kode='PENDAMPING' WHERE p.tipe='PENDAMPING' ON DUPLICATE KEY UPDATE nama=VALUES(nama),role_id=VALUES(role_id),penerima_id=VALUES(penerima_id),is_active=1,wajib_ganti_password=1;
INSERT INTO kegiatan (tahun_anggaran_id,nama_kegiatan,tanggal_input,tanggal_mulai,tanggal_selesai,tempat,status,total,created_by)
INSERT IGNORE INTO kegiatan_peserta (kegiatan_id,penerima_id) SELECT k.id,p.id FROM kegiatan k JOIN penerima p ON p.nama IN ('Ketua DPRD','Wakil Ketua I') WHERE k.nama_kegiatan LIKE 'Kegiatan Contoh %';
INSERT INTO kegiatan_biaya (kegiatan_peserta_id,jenis_biaya_id,volume,tarif) SELECT kp.id,j.id,1,750000 FROM kegiatan_peserta kp JOIN kegiatan k ON k.id=kp.kegiatan_id JOIN jenis_biaya j ON j.kode='TRANSPORT' WHERE k.nama_kegiatan LIKE 'Kegiatan Contoh %' AND NOT EXISTS (SELECT 1 FROM kegiatan_biaya kb WHERE kb.kegiatan_peserta_id=kp.id);
