USE anggaran_dprd;
UPDATE anggaran a JOIN sumber_dana sd ON sd.kode='APBD' SET a.sumber_dana_id=sd.id WHERE a.sumber_dana_id IS NULL;
SELECT t.id, CONCAT('Kegiatan Contoh ',x.n), CURDATE(), DATE_SUB(CURDATE(),INTERVAL x.n DAY), DATE_SUB(CURDATE(),INTERVAL x.n DAY), 'Dalam daerah', CASE x.n WHEN 1 THEN 'DRAFT' WHEN 2 THEN 'DIAJUKAN' WHEN 3 THEN 'DITOLAK' WHEN 4 THEN 'AKTIF' ELSE 'BATAL' END, 1500000, u.id
FROM tahun_anggaran t JOIN users u ON u.username='admin' JOIN (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5) x ON t.tahun=YEAR(CURDATE())
WHERE NOT EXISTS (SELECT 1 FROM kegiatan k WHERE k.nama_kegiatan=CONCAT('Kegiatan Contoh ',x.n));
